def reverse_number(n):
    result = 0
    while n > 0:
        result = result * 10 + n % 10
        n //= 10
    return result

def digital_root(n):
    while n >= 10:
        total = 0
        while n > 0:
            total += n % 10
            n //= 10
        n = total
    return n

def retry(statuses, max_attempts):
    attempt = 0
    status = None
    while attempt < max_attempts and attempt < len(statuses):
        status = statuses[attempt]
        attempt += 1
        if status < 500:
            break
    return status, attempt

