exercises.solution:
def is_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        i += 1
    return not stack

def undo_history(actions):
    history = []
    i = 0
    while i < len(actions):
        if actions[i] == "undo":
            if history:
                history.pop()
        else:
            history.append(actions[i])
        i += 1
    return history

