def int_sqrt(n):
    lo, hi = 0, n
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

def first_bad(commits, is_bad):
    lo, hi = 0, len(commits) - 1
    answer = None
    while lo <= hi:
        mid = (lo + hi) // 2
        if is_bad(commits[mid]):
            answer = commits[mid]
            hi = mid - 1
        else:
            lo = mid + 1
    return answer

