exercises.solution:
def bank_account(operations):
    balance = 0
    i = 0
    while i < len(operations):
        parts = operations[i].split()
        i += 1
        if parts[0] == "close":
            break
        amount = int(parts[1])
        if parts[0] == "deposit":
            balance += amount
        elif parts[0] == "withdraw" and amount <= balance:
            balance -= amount
    return balance

